import java.util.Scanner;

public class Main {
    static StringBuilder sb = new StringBuilder();

    static void yoz(int x) {
        if (sb.length() > 0) sb.append(" ");
        sb.append(x);
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt(), m = in.nextInt();
        int[][] a = new int[n][m];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                a[i][j] = in.nextInt();

        int top = 0, bottom = n - 1, left = 0, right = m - 1;
        while (top <= bottom && left <= right) {
            for (int j = left; j <= right; j++) yoz(a[top][j]);
            top++;
            for (int i = top; i <= bottom; i++) yoz(a[i][right]);
            right--;
            if (top <= bottom) {
                for (int j = right; j >= left; j--) yoz(a[bottom][j]);
                bottom--;
            }
            if (left <= right) {
                for (int i = bottom; i >= top; i--) yoz(a[i][left]);
                left++;
            }
        }
        System.out.println(sb);
    }
}

